package com.aydindemir.redis.controller; import java.util.Map; import org.springframework.web.bind.annotation.*; import com.aydindemir.redis.dto.*; import com.aydindemir.redis.redis.pubsub.*; import com.aydindemir.redis.redis.stream.RedisStreamService; import io.swagger.v3.oas.annotations.tags.Tag; import jakarta.validation.Valid;
@RestController @RequestMapping("/api/messaging") @Tag(name="05 - Pub/Sub & Redis Streams") public class RedisMessagingController { private final RedisPublisher pub; private final RedisSubscriber sub; private final RedisStreamService streams; public RedisMessagingController(RedisPublisher p,RedisSubscriber s,RedisStreamService r){pub=p;sub=s;streams=r;}
 @PostMapping("/pubsub") public Map<String,Object> publish(@Valid @RequestBody PublishRequest r){return Map.of("subscribers",pub.publish(r.message()));} @GetMapping("/pubsub/received") public Object received(){return sub.receivedMessages();}
 @PostMapping("/streams") public Map<String,Object> sp(@Valid @RequestBody StreamMessageRequest r){return Map.of("recordId",streams.publish(r.fields()).getValue());} @GetMapping("/streams") public Object sr(@RequestParam(defaultValue="10") long count){return streams.readFromStart(count);} @GetMapping("/streams/size") public Map<String,Long> size(){return Map.of("size",streams.size());} }
